/* ═══════════ TEMA CINPSI 2026 (redesign visual — etapa 1) ═══════════ */
:root{
  --navy:#04253D;--navy2:#0A3552;--gold:#B2680E;--gold-light:#FBF1E2;
  --bg:#F6F8FB;--surface:#FFF;--surface2:#F1F4F8;--border:#E7EBF1;--border2:#D6DCE6;
  --text:#1B2634;--text2:#3C4656;--text3:#7C8696;
  --accent:#15558A;--accent-light:#E8F0F8;--accent-mid:#2F7AB9;
  --radius:14px;--radius-sm:10px;
  --shadow:0 1px 2px rgba(16,32,52,.05),0 1px 1px rgba(16,32,52,.03);
  --shadow-md:0 8px 24px rgba(16,32,52,.08),0 2px 6px rgba(16,32,52,.04);
}
body{font-family:'Inter','DM Sans',system-ui,sans-serif;background:var(--bg);color:var(--text);-webkit-font-smoothing:antialiased}
button,input,select,textarea,.btn-primary,.btn-purple,.btn-ghost,.btn-save,.btn-save-purple,.btn-delete,.btn-logout,.nav-item,.form-input,.form-select,.login-input{font-family:'Inter','DM Sans',system-ui,sans-serif}
.cx-ico{width:18px;height:18px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0;display:block}

/* ── Menu lateral ── */
.sidebar{width:252px;min-width:252px;background:var(--navy);border-right:none;color:#fff;transition:width .2s,min-width .2s,transform .25s;z-index:60}
.sidebar-logo{padding:20px 18px 16px;border-bottom:1px solid rgba(255,255,255,.08);display:flex;align-items:center;justify-content:space-between;gap:8px}
.sb-brand-full{width:150px;height:auto;display:block}
.sb-brand-sym{height:34px;width:34px;display:none}
.sb-toggle{background:rgba(255,255,255,.07);border:none;color:rgba(255,255,255,.75);width:30px;height:30px;border-radius:8px;cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.sb-toggle:hover{background:rgba(255,255,255,.14);color:#fff}
.sb-toggle .cx-ico{width:16px;height:16px}
.sidebar-nav{padding:16px 12px}
.nav-section{color:rgba(255,255,255,.42);font-size:10px;letter-spacing:.1em;margin:20px 0 6px}
.nav-item{color:rgba(255,255,255,.74);padding:10px 12px;border-radius:10px;font-size:13.5px;font-weight:500;gap:12px;margin-bottom:2px;position:relative}
.nav-item:hover{background:rgba(255,255,255,.08);color:#fff}
.nav-item.active-admin,.nav-item.active-sup{background:#1C6AA8;color:#fff;font-weight:600;box-shadow:0 2px 8px rgba(0,0,0,.18)}
.nav-icon{width:18px;height:18px;display:flex;align-items:center;justify-content:center;font-size:0}
.nav-item .fin-badge-notif{margin-left:auto}
.sidebar-footer{border-top:1px solid rgba(255,255,255,.08);padding:14px 16px}
.sidebar-footer #fb-status{color:rgba(255,255,255,.6)!important}
.sidebar-footer .user-name{color:#fff}
.sidebar-footer .user-role-tag{color:rgba(255,255,255,.55)}
.sidebar-footer .user-avatar{background:rgba(255,255,255,.14)!important;color:#fff!important}
.sidebar-footer button{background:rgba(255,255,255,.06)!important;border:1px solid rgba(255,255,255,.14)!important;color:rgba(255,255,255,.82)!important;border-radius:10px!important}
.sidebar-footer button:hover{background:rgba(255,255,255,.13)!important;color:#fff!important}
.sidebar.collapsed{width:76px;min-width:76px}
.sidebar.collapsed .sb-brand-full{display:none}
.sidebar.collapsed .sb-brand-sym{display:block}
.sidebar.collapsed .sidebar-logo{flex-direction:column;padding:14px 8px;gap:10px}
.sidebar.collapsed .nav-section{font-size:0;height:1px;background:rgba(255,255,255,.1);margin:12px 10px}
.sidebar.collapsed .nav-item{font-size:0;justify-content:center;padding:11px 0;gap:0}
.sidebar.collapsed .nav-item .fin-badge-notif{position:absolute;top:4px;right:10px;font-size:9px;margin:0}
.sidebar.collapsed .sidebar-footer{padding:12px 8px}
.sidebar.collapsed .sidebar-footer>*:not(.user-chip){display:none!important}
.sidebar.collapsed .user-chip{justify-content:center;margin:0}
.sidebar.collapsed .user-chip>div:last-child{display:none}

/* ── Cabeçalho ── */
.topbar{background:rgba(255,255,255,.92);backdrop-filter:blur(8px);border-bottom:1px solid var(--border);padding:16px 32px;gap:16px}
.topbar-title{font-family:'Inter',sans-serif;font-size:22px;font-weight:700;color:var(--navy);letter-spacing:-.01em}
.topbar-sub{font-size:13px;color:var(--text3);margin-top:4px}
.cx-tb-left{display:flex;align-items:center;gap:12px;min-width:0}
.cx-tb-right{display:flex;align-items:center;gap:12px;margin-left:auto}
.cx-menu-btn{display:none;background:none;border:1px solid var(--border2);border-radius:10px;width:38px;height:38px;align-items:center;justify-content:center;color:var(--navy);cursor:pointer}
.cx-date{font-size:12.5px;color:var(--text3);white-space:nowrap}
.cx-search{position:relative;display:none}
.cx-search .cx-ico{position:absolute;left:12px;top:50%;transform:translateY(-50%);width:16px;height:16px;color:var(--text3);pointer-events:none}
.cx-search input{width:260px;border:1px solid var(--border);background:var(--surface2);border-radius:999px;padding:9px 14px 9px 36px;font-size:13px;color:var(--text);outline:none;transition:all .15s}
.cx-search input:focus{background:#fff;border-color:var(--accent-mid);box-shadow:0 0 0 3px rgba(47,122,185,.14);width:320px}
.cx-res{position:absolute;top:calc(100% + 8px);left:0;right:0;min-width:320px;background:#fff;border:1px solid var(--border);border-radius:14px;box-shadow:var(--shadow-md);max-height:380px;overflow:auto;display:none;z-index:80;padding:6px}
.cx-res.open{display:block}
.cx-res-it{display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:10px;cursor:pointer}
.cx-res-it:hover{background:var(--surface2)}
.cx-res-nm{font-size:13px;font-weight:600;color:var(--text)}
.cx-res-sb{font-size:11.5px;color:var(--text3)}
.cx-res-tag{margin-left:auto;font-size:10.5px;font-weight:600;padding:2px 8px;border-radius:999px;background:var(--accent-light);color:var(--accent);white-space:nowrap}
.cx-res-empty{padding:14px;font-size:12.5px;color:var(--text3);text-align:center}
.cx-bell{position:relative;display:none;background:none;border:1px solid var(--border);border-radius:50%;width:38px;height:38px;align-items:center;justify-content:center;color:var(--text2);cursor:pointer}
.cx-bell:hover{background:var(--surface2)}
.cx-bell-n{position:absolute;top:-3px;right:-3px;background:var(--gold);color:#fff;font-size:10px;font-weight:700;min-width:17px;height:17px;border-radius:9px;display:none;align-items:center;justify-content:center;padding:0 4px;border:2px solid #fff;box-sizing:content-box}
.cx-user{width:38px;height:38px;border-radius:50%;background:var(--navy);color:#fff;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:600}
.content{padding:28px 32px}

/* ── Componentes ── */
.card,.stat-card{border-radius:var(--radius);border:1px solid var(--border);box-shadow:var(--shadow)}
.btn-primary,.btn-save{background:var(--accent);border-radius:10px;font-weight:600}
.btn-primary:hover,.btn-save:hover{background:var(--navy2)}
.btn-ghost{border-radius:10px;border-color:var(--border2);color:var(--text2);font-weight:500}
.form-input,.form-select,.login-input,textarea.form-input{border-radius:10px;border-color:var(--border2)}
.form-input:focus,.form-select:focus{border-color:var(--accent-mid);box-shadow:0 0 0 3px rgba(47,122,185,.14);outline:none}
.modal{border-radius:18px}
.toast{background:var(--navy)}

/* ── Dashboard ── */
.cx-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:20px}
.cx-kpi{background:#fff;border:1px solid var(--border);border-radius:16px;padding:18px;display:flex;align-items:center;gap:14px;box-shadow:var(--shadow)}
.cx-kpi-ic{width:46px;height:46px;border-radius:14px;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.cx-kpi-ic .cx-ico{width:22px;height:22px}
.cx-kpi-v{font-size:26px;font-weight:700;color:var(--navy);line-height:1.1;letter-spacing:-.02em}
.cx-kpi-l{font-size:12.5px;color:var(--text2);margin-top:2px}
.cx-kpi-s{font-size:11.5px;margin-top:3px;color:var(--text3)}
.cx-kpi-s.bad{color:#B42318;font-weight:600}.cx-kpi-s.ok{color:#1E6B3A;font-weight:600}
.cx-grid2{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:16px;margin-bottom:20px}
.cx-card{background:#fff;border:1px solid var(--border);border-radius:16px;padding:20px 22px;box-shadow:var(--shadow)}
.cx-card-h{display:flex;align-items:center;gap:10px;margin-bottom:14px}
.cx-card-h h2{font-size:15px;font-weight:700;color:var(--navy);margin:0;letter-spacing:-.005em}
.cx-card-h .cx-ico{color:var(--gold);width:18px;height:18px}
.cx-card-h .cx-sp{margin-left:auto}
.cx-lk{font-size:12.5px;font-weight:600;color:var(--accent);background:none;border:none;cursor:pointer;padding:0}
.cx-lb{display:flex;flex-direction:column;gap:8px;max-height:330px;overflow:auto}
.cx-lr{display:flex;align-items:center;gap:12px;padding:11px 12px;border-radius:12px;cursor:pointer;border:1px solid transparent;transition:transform .1s}
.cx-lr:hover{transform:translateX(2px)}
.cx-lr.late{background:#FDF0EE;border-color:#F8D9D4}.cx-lr.today{background:#FDF5E6;border-color:#F5E3BF}
.cx-lav{width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:13px;flex-shrink:0}
.late .cx-lav{background:#F8D9D4;color:#9A2417}.today .cx-lav{background:#F5E3BF;color:#8A5300}
.cx-lm{flex:1;min-width:0}
.cx-ln{font-size:13.5px;font-weight:600;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cx-ln span{font-weight:400;color:var(--text3)}
.cx-ls{font-size:12px;color:var(--text3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cx-bd{font-size:11px;font-weight:700;padding:4px 10px;border-radius:8px;color:#fff;white-space:nowrap}
.late .cx-bd{background:#B42318}.today .cx-bd{background:var(--gold)}
.cx-lr>.cx-ico{color:var(--text3);width:16px;height:16px}
.cx-empty{padding:28px 10px;text-align:center;color:var(--text3);font-size:13px}
.cx-rings{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;text-align:center}
.cx-ring{position:relative;width:104px;height:104px;margin:4px auto 10px}
.cx-ring svg{width:104px;height:104px;transform:rotate(-90deg)}
.cx-ring b{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:700;color:var(--navy);letter-spacing:-.02em}
.cx-ring-t{font-size:12.5px;font-weight:600;color:var(--text)}
.cx-ring-s{font-size:11.5px;color:var(--text3);margin-top:2px}
.cx-conv-tools{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
@media(max-width:1100px){.cx-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.cx-grid2{grid-template-columns:1fr}.cx-date{display:none}}
@media(max-width:900px){
  .cx-menu-btn{display:flex}.sb-toggle{display:none}
  .sidebar,.sidebar.collapsed{display:flex!important;position:fixed;left:0;top:0;bottom:0;height:100vh;width:272px;min-width:272px;transform:translateX(-102%)}
  .sidebar.collapsed .sb-brand-full{display:block}.sidebar.collapsed .sb-brand-sym{display:none}
  .sidebar.collapsed .nav-item{font-size:13.5px;justify-content:flex-start;padding:10px 12px;gap:12px}
  .sidebar.collapsed .nav-section{font-size:10px;height:auto;background:none;margin:20px 0 6px}
  .sidebar.collapsed .sidebar-footer>*:not(.user-chip){display:block!important}
  .sidebar.collapsed .user-chip>div:last-child{display:block}
  .sidebar.collapsed .sidebar-logo{flex-direction:row;padding:20px 18px 16px}
  body.cx-open .sidebar{transform:none;box-shadow:0 0 40px rgba(0,0,0,.35)}
  #cx-overlay{display:none;position:fixed;inset:0;background:rgba(4,37,61,.5);z-index:55}
  body.cx-open #cx-overlay{display:block}
  .topbar{padding:12px 16px}.content{padding:16px}.cx-search input,.cx-search input:focus{width:200px}
}
@media(max-width:640px){.cx-kpis{grid-template-columns:1fr}.cx-search{display:none!important}.topbar-sub{display:none}.cx-rings{gap:4px}.cx-ring,.cx-ring svg{width:84px;height:84px}.cx-ring b{font-size:18px}}
body.view-dash #lembrete-banner{display:none!important}

.sidebar-footer button{padding:6px 8px!important;margin:0 0 4px!important;font-size:11px!important}
.sidebar-footer #btn-backup,.sidebar-footer #btn-restore{margin-top:0!important}
.sidebar-footer .user-chip{margin-bottom:6px}
.sidebar-footer #fb-status{margin-bottom:6px!important}
</style>

