};
function cxIco(n,cls){return '<svg class="cx-ico '+(cls||'')+'" viewBox="0 0 24 24" aria-hidden="true">'+(CX_ICONS[n]||'')+'</svg>';}
const CX_NAV={'dash-leads':'dash','leads':'leads','convertidos':'users','trilha':'compass','testes':'flask','nfse':'receipt','financeiro':'wallet','reunioes':'file','usuarios':'lock','minhaconta':'account'};
function cxNavIcons(){
  document.querySelectorAll('#sidebar-nav .nav-item').forEach(b=>{
    const k=(b.id||'').replace('nav-','');const ic=b.querySelector('.nav-icon');
    if(ic&&CX_NAV[k]) ic.innerHTML=cxIco(CX_NAV[k]);
    b.title=(b.textContent||'').replace(/\s+/g,' ').replace(/\d+$/,'').trim();
  });
}
function cxInit(){
  const adm=CU&&CU.role==='admin';
  const u=document.getElementById('cx-user');
  if(u&&CU){u.textContent=(CU.nome||'?').split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase();u.title=CU.nome||'';}
  const s=document.getElementById('cx-search'),b=document.getElementById('cx-bell');
  if(s) s.style.display=adm?'block':'none';
  if(b) b.style.display=adm?'flex':'none';
  try{ if(localStorage.getItem('cx_side')==='1'&&window.innerWidth>900) document.querySelector('.sidebar').classList.add('collapsed'); }catch(e){}
  document.getElementById('sidebar-nav').addEventListener('click',()=>document.body.classList.remove('cx-open'));
  document.addEventListener('click',e=>{const r=document.getElementById('cx-res');if(r&&!e.target.closest('#cx-search'))r.classList.remove('open');});
  cxBell();
}
function cxToggleSide(){
  if(window.innerWidth<=900){document.body.classList.toggle('cx-open');return;}
  const sb=document.querySelector('.sidebar');sb.classList.toggle('collapsed');
  try{localStorage.setItem('cx_side',sb.classList.contains('collapsed')?'1':'0');}catch(e){}
}
function cxOnView(name){
  document.body.classList.toggle('view-dash',name==='dash-leads');
  document.body.classList.remove('cx-open');
  const d=document.getElementById('cx-date');
  if(d){const t=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});d.textContent=t.charAt(0).toUpperCase()+t.slice(1);}
  cxNavIcons();cxBell();
}
function cxLembretes(){
  const hoje=new Date().toISOString().slice(0,10);
  const ls=loadLeads().filter(l=>l.prox_contato&&l.status!=='Fechado'&&l.status!=='Perdido'&&l.prox_contato<=hoje);
  ls.sort((a,b)=>a.prox_contato.localeCompare(b.prox_contato));
  return {hoje,lista:ls,atrasados:ls.filter(l=>l.prox_contato<hoje).length};
}
function cxBell(){
  const n=document.getElementById('cx-bell-n');if(!n||!CU||CU.role!=='admin')return;
  let c=0;try{c=cxLembretes().lista.length;}catch(e){}
  n.textContent=c>99?'99+':c;n.style.display=c?'flex':'none';
}
function cxBuscar(q){
  const box=document.getElementById('cx-res');if(!box)return;
  q=(q||'').trim().toLowerCase();
  if(q.length<2){box.classList.remove('open');return;}
  const dig=q.replace(/\D/g,'');
  const hit=(o)=>[o.paciente,o.responsavel,o.telefone,o.email].some(v=>v&&String(v).toLowerCase().includes(q))||(dig.length>=4&&String(o.telefone||'').replace(/\D/g,'').includes(dig));
  const out=[];
  loadLeads().filter(l=>l.status!=='Fechado'&&hit(l)).slice(0,6).forEach(l=>out.push({id:l.id,t:'lead',nm:l.paciente||l.responsavel||'—',sb:(l.responsavel&&l.paciente?l.responsavel+' · ':'')+(l.telefone||'')+(l.servico?' · '+l.servico:''),tag:l.status||'Lead'}));
  getConvertidos().filter(hit).slice(0,6).forEach(p=>out.push({id:p.id,t:'conv',nm:p.paciente||p.responsavel||'—',sb:(p.telefone||'')+(p.terapeuta?' · '+p.terapeuta:''),tag:p.ativo===false?'Inativo':'Paciente'}));
  window._cxRes=out.slice(0,10);
  box.innerHTML=window._cxRes.length?window._cxRes.map((r,i)=>`<div class="cx-res-it" onclick="cxAbrir(${i})"><div><div class="cx-res-nm">${esc(r.nm)}</div><div class="cx-res-sb">${esc(r.sb)}</div></div><span class="cx-res-tag">${esc(r.tag)}</span></div>`).join(''):'<div class="cx-res-empty">Nada encontrado</div>';
  box.classList.add('open');
}
function cxAbrir(i){
  const r=(window._cxRes||[])[i];if(!r)return;
  document.getElementById('cx-res').classList.remove('open');
  document.getElementById('cx-q').value='';
  if(r.t==='lead') openLeadModal(r.id); else openConvModal(r.id);
}
function cxDashTop(){
  const leads=loadLeads();
  const hoje=new Date(),anoMes=hoje.getFullYear()+'-'+String(hoje.getMonth()+1).padStart(2,'0');
  const andamento=leads.filter(l=>l.status!=='Fechado'&&l.status!=='Perdido');
  const lem=cxLembretes();
  const ativos=getConvertidos().filter(p=>p.ativo!==false).length;
  const convMes=loadConvAntigos().filter(p=>p.leadConvertido===true).length+leads.filter(l=>l.status==='Fechado'&&l.data&&l.data.startsWith(anoMes)).length;
  const fech=leads.filter(l=>l.status==='Fechado').length;
  const pct=leads.length?Math.round(fech/leads.length*100):0;
  const kpi=(ic,cor,bg,v,l,s,cls)=>`<div class="cx-kpi"><div class="cx-kpi-ic" style="background:${bg};color:${cor}">${cxIco(ic)}</div><div><div class="cx-kpi-v">${v}</div><div class="cx-kpi-l">${l}</div><div class="cx-kpi-s ${cls||''}">${s}</div></div></div>`;
  const kpis=`<div class="cx-kpis">`
    +kpi('users2','#B2680E','#FBF1E2',andamento.length,'Leads em andamento',lem.atrasados?lem.atrasados+(lem.atrasados>1?' atrasados':' atrasado'):'Nenhum atrasado',lem.atrasados?'bad':'ok')
    +kpi('usercheck','#15558A','#E8F0F8',ativos,'Pacientes ativos','Em acompanhamento')
    +kpi('userplus','#1E6B3A','#EAF3EF',convMes,'Convertidos no mês',hoje.toLocaleDateString('pt-BR',{month:'long',year:'numeric'}))
    +kpi('percent','#6C3483','#F5EEF8',pct+'%','Taxa de conversão',fech+' de '+leads.length+' leads')
    +`</div>`;
  const nomeL=l=>esc(l.responsavel||l.paciente||'—')+(l.paciente&&l.responsavel?` <span>/ ${esc(l.paciente)}</span>`:'');
  const rows=lem.lista.map(l=>{const at=l.prox_contato<lem.hoje;const ini=(l.responsavel||l.paciente||'?').trim()[0].toUpperCase();
    return `<div class="cx-lr ${at?'late':'today'}" onclick="openLeadModal('${l.id}')"><div class="cx-lav">${esc(ini)}</div><div class="cx-lm"><div class="cx-ln">${nomeL(l)}</div><div class="cx-ls">${esc([l.servico,l.telefone].filter(Boolean).join(' · ')||'Sem informações de contato')}</div></div><span class="cx-bd">${at?'Atrasado: '+fmtDate(l.prox_contato):'Hoje'}</span>${cxIco('chev')}</div>`;}).join('');
  const lemb=`<div class="cx-card"><div class="cx-card-h">${cxIco('bell')}<h2>Lembretes de contato · ${lem.lista.length}</h2><button class="cx-lk cx-sp" onclick="showView('leads')">Ver todos</button></div>`
    +(rows?`<div class="cx-lb">${rows}</div>`:'<div class="cx-empty">Nenhum contato pendente para hoje.</div>')+`</div>`;
  const ret=calcRetencao();
  const ring=(p,l,b,cor)=>{const C=2*Math.PI*42;return `<div><div class="cx-ring"><svg viewBox="0 0 104 104"><circle cx="52" cy="52" r="42" fill="none" stroke="#EDF0F5" stroke-width="9"/><circle cx="52" cy="52" r="42" fill="none" stroke="${cor}" stroke-width="9" stroke-linecap="round" stroke-dasharray="${C.toFixed(1)}" stroke-dashoffset="${(C*(1-Math.min(p,100)/100)).toFixed(1)}"/></svg><b>${p}%</b></div><div class="cx-ring-t">${l}</div><div class="cx-ring-s">${b} pacientes avaliados</div></div>`;};
  const retH=`<div class="cx-card"><div class="cx-card-h">${cxIco('chart')}<h2>Taxa de Retenção de Pacientes</h2></div>`
    +(ret?`<div class="cx-rings">${ring(ret.ret1,'Retidos após 1 mês',ret.base1,'#1E6B3A')}${ring(ret.ret3,'Retidos após 3 meses',ret.base3,'#15558A')}${ring(ret.ret6,'Retidos após 6 meses',ret.base6,'#B2680E')}</div>`:'<div class="cx-empty">Sem dados suficientes. Cadastre datas de conversão nos leads.</div>')+`</div>`;
  return kpis+`<div class="cx-grid2">${lemb}${retH}</div>`;
}

</script>
